∀ {K : Type u_1} {X : Type u_2} [inst : Fintype K] [inst_1 : Nonempty K] [inst_2 : PseudoMetricSpace X] {m : ℕ}
  [inst_3 : NeZero m] (c : APC.MetricIteration.Cloud (Fin m) X) (hkm : Fintype.card K ≤ m) (j : K),
  APC.MetricIteration.subsetOutput c hkm j ∈ Set.range c.points

∀ {K : Type u_1} {E : Type u_2} [inst : Fintype K] [inst_1 : Nonempty K] [inst_2 : NormedAddCommGroup E]
  [inst_3 : InnerProductSpace ℝ E] (N : ℕ) [inst_4 : NeZero N] (initial : APC.MetricIteration.Cloud (Fin N) E)
  (hw : ∀ (i : Fin N), 0 < initial.weights i) (ε : ℝ) (hε : 0 < ε),
  ε ≤ 1 →
    let t := APC.liftingSampleCount (ε / 10);
    have ht := ⋯;
    have e := APC.logStageError (↑N) 14400 ε;
    have δ := APC.MetricIteration.scheduledFailure N;
    have proxy := APC.EuclideanIteration.searchProxy N e δ t;
    have n := APC.logStop (↑N) 14400;
    ↑(APC.MetricIteration.size N (t * Fintype.card K) 4 e δ n) ≤
        APC.metricSizeGamma (t * Fintype.card K) 4 ε * 14400 ^ 2 ∧
      (APC.eventMass (APC.Adaptive.historyWeight (APC.EuclideanIteration.transition initial proxy) n) fun h =>
          ¬APC.EuclideanIteration.SummaryAPC initial (APC.EuclideanIteration.cloud N 4 e δ t initial proxy n h) ⋯ ε t
              ht) ≤
        1 / 2

∀ {K : Type u_1} {X : Type u_2} [inst : Fintype K] [inst_1 : Nonempty K] [inst_2 : Fintype X] [inst_3 : Nonempty X]
  [inst_4 : PseudoMetricSpace X] (N : ℕ) [inst_5 : NeZero N] (initial : APC.MetricIteration.Cloud (Fin N) X),
  (∀ (i : Fin N), 0 < initial.weights i) →
    ∀ (ε : ℝ) (hε : 0 < ε) (hε1 : ε ≤ 1),
      let k := Fintype.card K;
      let e := APC.logStageError (↑N) 14400 ε;
      let δ := APC.MetricIteration.scheduledFailure N;
      have proxy := APC.MetricIteration.exactProxy N e δ;
      let t := APC.logStop (↑N) 14400;
      have m := APC.MetricIteration.size N k 1 e δ t;
      have hkm := ⋯;
      ↑(m.choose k) ≤ (Real.exp 17 * 1265625 * 14400 ^ 2 * (1 + Real.log (APC.metricSizeBase k 1 ε)) / ε ^ 2) ^ k ∧
        (APC.eventMass (APC.Adaptive.historyWeight (APC.MetricIteration.transition initial proxy) t) fun h =>
            ¬APC.Approximate (APC.cost initial.points initial.weights) (4 + ε)
                (APC.MetricIteration.subsetOutput (APC.MetricIteration.cloud N 1 e δ initial proxy t h) hkm)) ≤
          1 / 2

